-- FUNC13 Obras Públicas, Engenharia, Medições, Diário e Fiscalização
create schema if not exists sigov;
create table if not exists sigov.obras_obra (
id bigint generated by default as identity primary key,codigo varchar(60) not null,nome varchar(240) not null,descricao text,tipo_obra varchar(100) not null,unidade varchar(180),localidade varchar(180) not null,endereco text,latitude numeric(10,7),longitude numeric(10,7),valor_estimado numeric(18,2) not null default 0,valor_contratado numeric(18,2) not null default 0,inicio_previsto date not null,fim_previsto date not null,inicio_real date,fim_real date,status varchar(24) not null default 'PLANEJADA',fiscal varchar(180),observacoes text,justificativa text,contrato_referencia varchar(180),fonte_recurso varchar(180),tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,
constraint ck_obras_obra_status check(status in('PLANEJADA','LICITADA','CONTRATADA','EM_EXECUCAO','PARALISADA','CONCLUIDA','CANCELADA','RESCINDIDA')),constraint ck_obras_obra_valores check(valor_estimado>=0 and valor_contratado>=0),constraint ck_obras_obra_datas check(fim_previsto>=inicio_previsto and (fim_real is null or inicio_real is null or fim_real>=inicio_real)),constraint ck_obras_obra_justificativa check(status not in('PARALISADA','CANCELADA','RESCINDIDA') or nullif(btrim(justificativa),'') is not null),constraint uq_obras_obra_contexto unique(tenant_id,entidade_id,codigo));
create table if not exists sigov.obras_responsavel_tecnico (id bigint generated by default as identity primary key,nome varchar(200) not null,registro_profissional varchar(100) not null,conselho varchar(20),especialidade varchar(100),tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.obras_projeto (id bigint generated by default as identity primary key,obra_id bigint not null references sigov.obras_obra(id),codigo varchar(80) not null default '',descricao text not null,status varchar(30) not null default 'RASCUNHO',valor numeric(18,2),data date,justificativa text,dados jsonb not null default '{}'::jsonb,versao integer not null default 1,art_rrt varchar(100),responsavel_tecnico varchar(180),tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,constraint ck_obras_projeto_valor check(valor is null or valor>=0),constraint ck_obras_projeto_status check(status in('EM_ELABORACAO','APROVADO','SUBSTITUIDO','CANCELADO')),constraint ck_obras_projeto_justificativa check(status<>'CANCELADA' or nullif(btrim(justificativa),'') is not null),constraint ck_obras_projeto_substituido check(status<>'SUBSTITUIDO' or nullif(btrim(justificativa),'') is not null));
create table if not exists sigov.obras_orcamento (id bigint generated by default as identity primary key,obra_id bigint not null references sigov.obras_obra(id),codigo varchar(80) not null default '',descricao text not null,status varchar(30) not null default 'RASCUNHO',valor numeric(18,2),data date,justificativa text,dados jsonb not null default '{}'::jsonb,tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,constraint ck_obras_orcamento_valor check(valor is null or valor>=0));
