create table if not exists sigov.obras_cronograma (id bigint generated by default as identity primary key,obra_id bigint not null references sigov.obras_obra(id),codigo varchar(80) not null default '',descricao text not null,status varchar(30) not null default 'RASCUNHO',valor numeric(18,2),data date,justificativa text,dados jsonb not null default '{}'::jsonb,percentual_previsto numeric(7,4) not null default 0,percentual_realizado numeric(7,4) not null default 0,data_fim_real date,tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,constraint ck_obras_cronograma_valor check(valor is null or valor>=0),constraint ck_obras_cronograma_percentuais check(percentual_previsto between 0 and 100 and percentual_realizado between 0 and 100));
create table if not exists sigov.obras_reprogramacao (id bigint generated by default as identity primary key,obra_id bigint not null references sigov.obras_obra(id),codigo varchar(80) not null default '',descricao text not null,status varchar(30) not null default 'RASCUNHO',valor numeric(18,2),data date,justificativa text,dados jsonb not null default '{}'::jsonb,tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,constraint ck_obras_reprogramacao_valor check(valor is null or valor>=0));
