create table if not exists sigov.obras_medicao (id bigint generated by default as identity primary key,obra_id bigint not null references sigov.obras_obra(id),codigo varchar(80) not null default '',descricao text not null,status varchar(30) not null default 'RASCUNHO',valor numeric(18,2),data date,justificativa text,dados jsonb not null default '{}'::jsonb,homologada_at timestamptz,percentual_fisico numeric(7,4) default 0,periodo_inicio date,periodo_fim date,responsavel_tecnico varchar(180),fiscal varchar(180),tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,constraint ck_obras_medicao_valor check(valor is null or valor>=0),constraint ck_obras_medicao_status check(status in('RASCUNHO','EM_ANALISE','APROVADA','HOMOLOGADA','CANCELADA')),constraint ck_obras_medicao_justificativa check(status<>'CANCELADA' or nullif(btrim(justificativa),'') is not null));
