create table if not exists sigov.obras_auditoria (id bigint generated by default as identity primary key,acao varchar(50) not null,recurso varchar(100) not null,registro_id bigint,usuario_id bigint,antes jsonb,depois jsonb,correlation_id varchar(100),ip inet,codigo varchar(80) not null default '',descricao text not null default '',status varchar(30) not null default 'REGISTRADA',valor numeric(18,2),data date,dados jsonb not null default '{}'::jsonb,obra_id bigint,tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create or replace function sigov.func13_validar_medicao_item() returns trigger language plpgsql as $$ declare saldo numeric; begin select oi.valor_total-coalesce(sum(mi.valor),0) into saldo from sigov.obras_orcamento_item oi left join sigov.obras_medicao_item mi on mi.orcamento_item_id=oi.id and mi.id<>coalesce(new.id,0) and not mi.is_deleted left join sigov.obras_medicao m on m.id=mi.medicao_id and m.status<>'CANCELADA' where oi.id=new.orcamento_item_id group by oi.valor_total; if new.valor>coalesce(saldo,0) then raise exception 'Medição excede saldo do item orçamentário'; end if; return new; end $$;
drop trigger if exists trg_func13_medicao_saldo on sigov.obras_medicao_item; create trigger trg_func13_medicao_saldo before insert or update on sigov.obras_medicao_item for each row execute function sigov.func13_validar_medicao_item();
create or replace function sigov.func13_bloquear_orcamento_aprovado() returns trigger language plpgsql as $$ begin if old.status='APROVADO' then raise exception 'Orçamento aprovado exige reprogramação'; end if; return new; end $$;
drop trigger if exists trg_func13_orcamento_imutavel on sigov.obras_orcamento; create trigger trg_func13_orcamento_imutavel before update or delete on sigov.obras_orcamento for each row execute function sigov.func13_bloquear_orcamento_aprovado();
